    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous horizontal bands containing foreground cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # When equal-height bands repeat the same motif but one extends farther
    # right, transfer that part of its foreground mask to the shorter band.
    paired = set()
    for i in range(len(bands)):
        a, b = bands[i]
        for j in range(i + 1, len(bands)):
            c, d = bands[j]
            if b - a != d - c:
                continue
            right_a = max(x for rr in range(a, b)
                          for x, v in enumerate(grid[rr]) if v != bg)
            right_c = max(x for rr in range(c, d)
                          for x, v in enumerate(grid[rr]) if v != bg)
            if right_a == right_c:
                continue

            src_start, src_end, dst_start, short_right = (
                (a, b, c, right_c) if right_a > right_c
                else (c, d, a, right_a)
            )
            far_right = max(right_a, right_c)
            for k in range(b - a):
                for x in range(short_right + 1, far_right + 1):
                    if grid[src_start + k][x] != bg and grid[dst_start + k][x] == bg:
                        out[dst_start + k][x] = 1
            paired.update((i, j))

    # In other bands, extend rows that reach the band's rightmost foreground.
    for i, (start, end) in enumerate(bands):
        if i in paired:
            continue
        rightmost = max(x for rr in range(start, end)
                        for x, v in enumerate(grid[rr]) if v != bg)
        for rr in range(start, end):
            if grid[rr][rightmost] != bg:
                for x in range(rightmost + 1, w):
