def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous groups of rows containing foreground cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Repeated bands can have the same pattern but one may be truncated.
    for i in range(len(bands)):
        a0, a1 = bands[i]
        for j in range(i + 1, len(bands)):
            b0, b1 = bands[j]
            if a1 - a0 != b1 - b0:
                continue

            ra = max(c for rr in range(a0, a1)
                     for c, v in enumerate(grid[rr]) if v != bg)
            rb = max(c for rr in range(b0, b1)
                     for c, v in enumerate(grid[rr]) if v != bg)

            # d aligns band B to band A: B column c corresponds to A column c-d.
            best_d, best_score = 0, -1
            for d in range(-4, 5):
                lo = max(0, -d)
                hi = min(ra, rb - d, w - 1, w - 1 - d)
                if hi < lo:
                    continue
                matches = total = 0
                for k in range(a1 - a0):
                    for x in range(lo, hi + 1):
                        total += 1
                        if grid[a0 + k][x] == grid[b0 + k][x + d]:
                            matches += 1
                score = matches / total
                if score > best_score or (score == best_score and abs(d) < abs(best_d)):
                    best_d, best_score = d, score

            d = best_d
            # Copy the longer continuation into the shorter band, using 1
            # to mark the newly transferred foreground cells.
            if ra > rb - d:
                for k in range(a1 - a0):
                    for cb in range(rb + 1, min(w, ra + d + 1)):
                        ca = cb - d
                        if 0 <= ca < w and grid[a0 + k][ca] != bg and grid[b0 + k][cb] == bg:
                            out[b0 + k][cb] = 1
            elif rb - d > ra:
                for k in range(a1 - a0):
                    for ca in range(ra + 1, min(w, rb - d + 1)):
                        cb = ca + d
                        if 0 <= cb < w and grid[b0 + k][cb] != bg and grid[a0 + k][ca] == bg:
                            out[a0 + k][ca] = 1

    return out
